#[async_trait]
pub trait StreamServiceMcpServer: Send + Sync + 'static {
    async fn apply_stream_retention(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn compact_stream(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn create_stream(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn delete_stream(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn export_stream(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn get_stream(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn list_streams(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn update_stream(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn verify_stream(&self, args: Value) -> std::result::Result<Value, McpError>;
}

pub struct StreamServiceMcpHandler<T: StreamServiceMcpServer> { inner: Arc<T> }

impl<T: StreamServiceMcpServer> Clone for StreamServiceMcpHandler<T> {
    fn clone(&self) -> Self { Self { inner: Arc::clone(&self.inner) } }
}

impl<T: StreamServiceMcpServer> StreamServiceMcpHandler<T> {
    pub fn new(svc: T) -> Self { Self { inner: Arc::new(svc) } }

    pub fn tools() -> Vec<Tool> {
        vec![
            make_tool("stream_service-apply_stream_retention_v1", "Runs the stream's retention policy now rather than at the next pass (SPEC section 43). With `validate_only`, removes nothing and says what would go.", STREAM_SERVICE__APPLY_STREAM_RETENTION_SCHEMA_JSON, STREAM_SERVICE__APPLY_STREAM_RETENTION_OUTPUT_SCHEMA_JSON, Value::Null, "", Value::Null),
            make_tool("stream_service-compact_stream_v1", "Merges small chunks, re-chooses encodings and rebuilds the index for a stream's history (SPEC section 42). Crash-safe and lossless: every sample readable before is readable after, bit for bit. Ingestion continues meanwhile.", STREAM_SERVICE__COMPACT_STREAM_SCHEMA_JSON, STREAM_SERVICE__COMPACT_STREAM_OUTPUT_SCHEMA_JSON, Value::Null, "", Value::Null),
            make_tool("stream_service-create_stream_v1", "Creates a stream.", STREAM_SERVICE__CREATE_STREAM_SCHEMA_JSON, STREAM_SERVICE__CREATE_STREAM_OUTPUT_SCHEMA_JSON, Value::Null, "", Value::Null),
            make_tool("stream_service-delete_stream_v1", "Deletes a stream that no signal records into and that holds no samples; FAILED_PRECONDITION with ERROR_REASON_RESOURCE_NOT_EMPTY otherwise.", STREAM_SERVICE__DELETE_STREAM_SCHEMA_JSON, STREAM_SERVICE__DELETE_STREAM_OUTPUT_SCHEMA_JSON, Value::Null, "", Value::Null),
            make_tool("stream_service-export_stream_v1", "Writes a stream's samples in an interval to a file in an interchange format (SPEC section 44), streaming and in bounded memory.", STREAM_SERVICE__EXPORT_STREAM_SCHEMA_JSON, STREAM_SERVICE__EXPORT_STREAM_OUTPUT_SCHEMA_JSON, Value::Null, "", Value::Null),
            make_tool("stream_service-get_stream_v1", "Reads one stream, with its current totals.", STREAM_SERVICE__GET_STREAM_SCHEMA_JSON, STREAM_SERVICE__GET_STREAM_OUTPUT_SCHEMA_JSON, json!({"readOnlyHint": true, "openWorldHint": false
}), "Get stream", Value::Null),
            make_tool("stream_service-list_streams_v1", "Lists streams in name order.", STREAM_SERVICE__LIST_STREAMS_SCHEMA_JSON, STREAM_SERVICE__LIST_STREAMS_OUTPUT_SCHEMA_JSON, json!({"readOnlyHint": true, "openWorldHint": false
}), "List streams", Value::Null),
            make_tool("stream_service-update_stream_v1", "Changes the fields named in `update_mask`. Tightening `retention` takes effect at the next retention pass, never inside this call.", STREAM_SERVICE__UPDATE_STREAM_SCHEMA_JSON, STREAM_SERVICE__UPDATE_STREAM_OUTPUT_SCHEMA_JSON, Value::Null, "", Value::Null),
            make_tool("stream_service-verify_stream_v1", "Reads and checks every chunk of a stream's sealed segments, through whatever startup skipped. Changes no stored byte. Damage found is reported in the result and counted in the stream's `corrupt_sample_count`.", STREAM_SERVICE__VERIFY_STREAM_SCHEMA_JSON, STREAM_SERVICE__VERIFY_STREAM_OUTPUT_SCHEMA_JSON, Value::Null, "", Value::Null),
        ]
    }

    pub fn resources() -> Vec<Resource> {
        vec![
        ]
    }

    pub fn resource_templates() -> Vec<ResourceTemplate> {
        vec![
            serde_json::from_value(json!({
                "uriTemplate": "stream://streams/{stream}", "name": "Stream",
                "description": "Stream resource (streams/{stream})", "mimeType": "application/json"
            })).expect("generated resource template must be valid"),
        ]
    }
}

impl<T: StreamServiceMcpServer> ServerHandler for StreamServiceMcpHandler<T> {
    fn get_info(&self) -> ServerConfig {
        ServerConfig::new(
            ServerCapabilities::builder()
                .enable_tools()
                .enable_resources()
                .build(),
        )
        .with_server_info(Implementation::new("StreamService", "0.1.0"))
    }

    async fn list_tools(&self, _: Option<PaginatedRequestParams>, _: RequestContext<RoleServer>) -> std::result::Result<ListToolsResult, McpError> {
        Ok(ListToolsResult::with_all_items(Self::tools()))
    }
    async fn call_tool(&self, request: CallToolRequestParams, _context: RequestContext<RoleServer>) -> std::result::Result<CallToolResponse, McpError> {
        let args = request.arguments.map_or_else(|| Value::Object(Default::default()), Value::Object);
        match request.name.as_ref() {
            "stream_service-apply_stream_retention_v1" => {
                let result = self.inner.apply_stream_retention(args).await?;
                let text = serde_json::to_string(&result)
                    .map_err(|e| McpError::internal_error(format!("serialize response: {e}"), None))?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            "stream_service-compact_stream_v1" => {
                let result = self.inner.compact_stream(args).await?;
                let text = serde_json::to_string(&result)
                    .map_err(|e| McpError::internal_error(format!("serialize response: {e}"), None))?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            "stream_service-create_stream_v1" => {
                let result = self.inner.create_stream(args).await?;
                let text = serde_json::to_string(&result)
                    .map_err(|e| McpError::internal_error(format!("serialize response: {e}"), None))?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            "stream_service-delete_stream_v1" => {
                let result = self.inner.delete_stream(args).await?;
                let text = serde_json::to_string(&result)
                    .map_err(|e| McpError::internal_error(format!("serialize response: {e}"), None))?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            "stream_service-export_stream_v1" => {
                let result = self.inner.export_stream(args).await?;
                let text = serde_json::to_string(&result)
                    .map_err(|e| McpError::internal_error(format!("serialize response: {e}"), None))?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            "stream_service-get_stream_v1" => {
                let result = self.inner.get_stream(args).await?;
                let text = serde_json::to_string(&result)
                    .map_err(|e| McpError::internal_error(format!("serialize response: {e}"), None))?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            "stream_service-list_streams_v1" => {
                let result = self.inner.list_streams(args).await?;
                let text = serde_json::to_string(&result)
                    .map_err(|e| McpError::internal_error(format!("serialize response: {e}"), None))?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            "stream_service-update_stream_v1" => {
                let result = self.inner.update_stream(args).await?;
                let text = serde_json::to_string(&result)
                    .map_err(|e| McpError::internal_error(format!("serialize response: {e}"), None))?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            "stream_service-verify_stream_v1" => {
                let result = self.inner.verify_stream(args).await?;
                let text = serde_json::to_string(&result)
                    .map_err(|e| McpError::internal_error(format!("serialize response: {e}"), None))?;
                Ok(CallToolResult::success(vec![ContentBlock::text(text)]).into())
            }
            _ => Err(McpError::internal_error(format!("unknown tool: {}", request.name), None)),
        }
    }

    async fn list_resources(&self, _: Option<PaginatedRequestParams>, _: RequestContext<RoleServer>) -> std::result::Result<ListResourcesResult, McpError> {
        Ok(ListResourcesResult::with_all_items(Self::resources()))
    }

    async fn list_resource_templates(&self, _: Option<PaginatedRequestParams>, _: RequestContext<RoleServer>) -> std::result::Result<ListResourceTemplatesResult, McpError> {
        Ok(ListResourceTemplatesResult::with_all_items(Self::resource_templates()))
    }

    async fn read_resource(&self, request: ReadResourceRequestParams, _: RequestContext<RoleServer>) -> std::result::Result<ReadResourceResponse, McpError> {
        Ok(ReadResourceResult::new(vec![ResourceContents::text("{}", request.uri)]).into())
    }
}

pub const STREAM_SERVICE_MCP_DEFAULT_BASE_PATH: &str = "/norn/stream/v1/streamservice/mcp";

pub struct StreamServiceMcpTransportConfig {
    pub transport: String,
    pub host: String,
    pub port: u16,
    pub base_path: String,
}

impl Default for StreamServiceMcpTransportConfig {
    fn default() -> Self {
        Self { transport: "streamable-http".into(), host: "0.0.0.0".into(), port: 8080,
               base_path: STREAM_SERVICE_MCP_DEFAULT_BASE_PATH.into() }
    }
}

pub async fn serve_stream_service_mcp_stdio<T: StreamServiceMcpServer>(svc: T) -> std::result::Result<(), Box<dyn std::error::Error>> {
    let handler = StreamServiceMcpHandler::new(svc);
    handler.serve(rmcp::transport::stdio()).await?.waiting().await?;
    Ok(())
}

pub async fn serve_stream_service_mcp<T: StreamServiceMcpServer>(
    svc: T, config: StreamServiceMcpTransportConfig,
) -> std::result::Result<(), Box<dyn std::error::Error>> {
    let handler = StreamServiceMcpHandler::new(svc);
    let transports: Vec<&str> = config.transport.split(',').map(|s| s.trim()).filter(|s| !s.is_empty()).collect();
    let has_stdio = transports.iter().any(|t| *t == "stdio");
    let http_transport = transports.iter().find(|t| **t == "sse" || **t == "streamable-http").copied();

    if let Some(_ht) = http_transport {
        use rmcp::transport::streamable_http_server::{
            StreamableHttpServerConfig, StreamableHttpService, session::local::LocalSessionManager,
        };
        let h = handler.clone();
        let http_config = StreamableHttpServerConfig::default().with_sse_retry(None);
        let http_service = StreamableHttpService::new(
            move || Ok(h.clone()), Arc::new(LocalSessionManager::default()),
            http_config,
        );
        let app = axum::Router::new().nest_service(&config.base_path, http_service);
        let addr = format!("{}:{}", config.host, config.port);
        let listener = tokio::net::TcpListener::bind(&addr).await?;
        if has_stdio {
            tokio::spawn(async move { axum::serve(listener, app).await.expect("HTTP server failed"); });
        } else {
            axum::serve(listener, app).await?;
            return Ok(());
        }
    }

    if has_stdio {
        handler.serve(rmcp::transport::stdio()).await?.waiting().await?;
    } else if http_transport.is_none() {
        return Err(format!("unsupported transport(s): {}", config.transport).into());
    }
    Ok(())
}
